import React from 'react';
import jsPDF from 'jspdf';

function DownloadPDF({ resumeData }) {
  const handleDownload = () => {
    const doc = new jsPDF();
    let y = 15;
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(22);
    doc.text(resumeData.name || '', 105, y, { align: 'center' });
    y += 10;
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(12);
    doc.text(`Email: ${resumeData.email || ''}    Phone: ${resumeData.phone || ''}`, 105, y, { align: 'center' });
    y += 15;
    doc.setFontSize(14);
    doc.setFont('helvetica', 'bold');
    doc.text('Professional Summary', 10, y);
    y += 7;
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(12);
    doc.text(doc.splitTextToSize(resumeData.summary || '', 190), 10, y);
    y += 20;
    doc.setFontSize(14);
    doc.setFont('helvetica', 'bold');
    doc.text('Experience', 10, y);
    y += 7;
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(12);
    doc.text(doc.splitTextToSize(resumeData.experience || '', 190), 10, y);
    y += 20;
    doc.setFontSize(14);
    doc.setFont('helvetica', 'bold');
    doc.text('Education', 10, y);
    y += 7;
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(12);
    doc.text(doc.splitTextToSize(resumeData.education || '', 190), 10, y);
    y += 20;
    doc.setFontSize(14);
    doc.setFont('helvetica', 'bold');
    doc.text('Skills', 10, y);
    y += 7;
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(12);
    let skillsArr = Array.isArray(resumeData.skills)
      ? resumeData.skills
      : (resumeData.skills || '').split(',');
    skillsArr = skillsArr.map(s => s.trim()).filter(Boolean);
    skillsArr.forEach((skill, i) => {
      doc.text(`• ${skill}`, 14, y + i * 7);
    });
    doc.save('resume.pdf');
  };

  return (
    <button onClick={handleDownload} style={{marginTop: '16px', padding: '10px 20px', background: '#28a745', color: '#fff', border: 'none', borderRadius: '4px', cursor: 'pointer'}}>
      Download as PDF
    </button>
  );
}

export default DownloadPDF;
